/* CSS Custom Properties */
:root {
  --color-primary: #1a5c3a;
  --color-primary-dark: #0f3d28;
  --color-primary-light: #d4edda;
  --color-accent: #f59e0b;
  --color-accent-on-dark: #fbbf24;
  --color-text-dark: #1f2937;
  --color-text-light: #f9fafb;
  --color-border: #e5e7eb;
  --color-success: #10b981;
  --color-error: #ef4444;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --line-height-tight: 1.3;
  --line-height-normal: 1.6;
}

/* Reset and Base Typography */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: var(--line-height-normal);
  color: var(--color-text-dark);
  background-color: var(--color-text-light);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  line-height: var(--line-height-tight);
  font-weight: 700;
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: clamp(1.75rem, 5vw, 2.5rem);
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2rem);
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.5rem);
}

p {
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: color 0.3s ease;
}

a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  width: 100%;
}

/* Header */
.site-header {
  background-color: var(--color-text-light);
  border-bottom: 2px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.logo {
  display: inline-block;
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 4vw, 1.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--color-primary);
  text-decoration: none;
  border-top: 3px double var(--color-accent);
  border-bottom: 3px double var(--color-accent);
  padding: 0.3rem 0.6rem;
  transition: color 0.3s ease;
}

.logo:hover {
  color: var(--color-primary-dark);
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

/* Footer */
.site-footer {
  background-color: var(--color-primary);
  color: var(--color-text-light);
  padding: var(--spacing-xl) var(--spacing-md);
  margin-top: var(--spacing-2xl);
}

.site-footer p {
  margin-bottom: var(--spacing-sm);
  font-size: 0.9rem;
}

.site-footer a {
  color: var(--color-accent-on-dark);
}

.site-footer a:hover {
  color: var(--color-text-light);
}

/* Buttons */
button,
.btn {
  display: inline-block;
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  text-align: center;
  border: none;
  border-radius: 0.375rem;
  background-color: var(--color-primary);
  color: var(--color-text-light);
  cursor: pointer;
  transition: background-color 0.3s ease, transform 0.2s ease;
  text-decoration: none;
}

button:hover,
.btn:hover {
  background-color: var(--color-primary-dark);
}

button:focus,
.btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active,
.btn:active {
  transform: scale(0.98);
}

/* Forms */
form {
  width: 100%;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
  color: var(--color-text-dark);
}

input[type="text"],
input[type="email"],
input[type="tel"],
textarea {
  display: block;
  width: 100%;
  min-height: 44px;
  padding: var(--spacing-sm);
  font-family: var(--font-sans);
  font-size: 1rem;
  border: 2px solid var(--color-border);
  border-radius: 0.375rem;
  background-color: var(--color-text-light);
  color: var(--color-text-dark);
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
  margin-bottom: var(--spacing-md);
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(26, 92, 58, 0.1);
}

textarea {
  min-height: 100px;
  resize: vertical;
}

/* Cards */
.card {
  background-color: var(--color-text-light);
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  overflow: hidden;
  transition: box-shadow 0.3s ease, transform 0.3s ease;
}

.card:hover {
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.1);
  transform: translateY(-4px);
}

.card-body {
  padding: var(--spacing-lg);
}

.card-title {
  margin-top: 0;
}

.card-meta {
  font-size: 0.9rem;
  color: #6b7280;
  margin-bottom: var(--spacing-sm);
}

/* Grid */
.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

/* Responsive Design */
@media (min-width: 601px) {
  .container {
    padding: 0 var(--spacing-lg);
  }

  .site-header {
    padding: var(--spacing-lg) 0;
  }

  .site-footer {
    padding: var(--spacing-2xl) var(--spacing-lg);
  }

  button,
  .btn {
    padding: var(--spacing-md) var(--spacing-xl);
  }

  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 600px) {
  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.25rem;
  }

  .site-header {
    padding: var(--spacing-sm) 0;
  }

  .logo {
    font-size: 1.25rem;
    padding: 0.25rem 0.5rem;
  }

  .container {
    padding: 0 var(--spacing-md);
  }

  button,
  .btn {
    width: 100%;
    padding: var(--spacing-md) var(--spacing-sm);
  }

  .grid {
    gap: var(--spacing-md);
  }

  .grid-2,
  .grid-3 {
    grid-template-columns: 1fr;
  }

  .site-footer {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .site-footer p {
    font-size: 0.85rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

