.index-latest h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
  color: var(--color-primary);
}

.index-newsletter {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-text-light);
  padding: var(--spacing-2xl) var(--spacing-md);
}

.index-newsletter-content {
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
}

.index-newsletter h2 {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
}

.index-newsletter > .container > p {
  color: var(--color-text-light);
  margin-bottom: var(--spacing-lg);
  font-size: 1.1rem;
}

.index-newsletter-form {
  background-color: rgba(255, 255, 255, 0.1);
  padding: var(--spacing-lg);
  border-radius: 0.5rem;
  backdrop-filter: blur(10px);
}

.index-form-group {
  margin-bottom: var(--spacing-md);
  text-align: left;
}

.index-form-group label {
  color: var(--color-text-light);
  font-weight: 600;
  display: block;
  margin-bottom: var(--spacing-xs);
}

.index-form-group input {
  width: 100%;
  padding: var(--spacing-sm);
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 0.375rem;
  font-size: 1rem;
  background-color: rgba(255, 255, 255, 0.95);
  color: var(--color-text-dark);
  transition: border-color 0.3s ease;
  min-height: 44px;
}

.index-form-group input:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(245, 158, 11, 0.2);
}

.index-newsletter-btn {
  width: 100%;
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
  font-weight: 700;
  min-height: 44px;
  padding: var(--spacing-md);
  border: none;
  border-radius: 0.375rem;
  cursor: pointer;
  font-size: 1rem;
  transition: background-color 0.3s ease, transform 0.2s ease;
}

.index-newsletter-btn:hover {
  background-color: #fcd34d;
}

.index-newsletter-btn:focus {
  outline: 3px solid rgba(255, 255, 255, 0.5);
  outline-offset: 2px;
}

.index-newsletter-btn:active {
  transform: scale(0.98);
}

.index-newsletter-note {
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.8);
  margin-top: var(--spacing-md);
  margin-bottom: 0;
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-2xl) var(--spacing-lg);
  }

  .index-featured {
    padding: var(--spacing-2xl) var(--spacing-lg);
  }

  .index-latest {
    padding: var(--spacing-2xl) var(--spacing-lg);
  }

  .index-newsletter {
    padding: var(--spacing-2xl) var(--spacing-lg);
  }

  .index-form-group {
    margin-bottom: var(--spacing-md);
  }
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .index-hero-tagline {
    font-size: 1.1rem;
  }

  .index-featured-article {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .index-featured {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .index-latest {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .index-newsletter {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .index-newsletter-content {
    max-width: 100%;
  }

  .index-newsletter-form {
    padding: var(--spacing-md);
  }

  .index-form-group {
    margin-bottom: var(--spacing-sm);
  }

  .index-form-group input {
    padding: var(--spacing-sm);
  }
}
